func (q *Queries) ResetRSSIncompleteRecoveryEntries(ctx context.Context, arg ResetRSSIncompleteRecoveryEntriesParams) ([]RssEntry, error) {
	rows, err := q.db.Query(ctx, resetRSSIncompleteRecoveryEntries, arg.SubscriptionID, arg.SourceEpisodes)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RssEntry{}
	for rows.Next() {
		var i RssEntry
		if err := rows.Scan(
			&i.ID,
			&i.SubscriptionID,
			&i.ReleaseCandidateID,
			&i.IdentityKey,
			&i.Guid,
			&i.Btih,
			&i.CanonicalUrl,
			&i.Title,
			&i.PublishedAt,
			&i.Status,
			&i.EnqueueAttempts,
			&i.LastErrorCode,
			&i.LastErrorMessage,
			&i.UpstreamPayload,
			&i.DiscoveredAt,
			&i.EnqueuedAt,
			&i.UpdatedAt,
			&i.DownloadUri,
			&i.Downloadable,
			&i.RejectionReasons,
			&i.SourceSeason,
			&i.SourceEpisode,
			&i.DuplicateCount,
			&i.LastErrorRetryable,
			&i.ImportedAt,
			&i.CoordinateSource,
			&i.AgentResolutionID,
			&i.FulfillmentSource,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

